#
# SurgicalPlanningWidget
#


class _SurgicalPlanningLayoutObserver(qt.QObject):
    """Observe logical width/font changes without touching compound controls."""

    def __init__(self, widget):
        qt.QObject.__init__(self, widget.uiWidget)
        self.widget = widget

    def eventFilter(self, watched, event):
        if not self.widget.uiWidget.isVisible():
            return False
        eventType = event.type()
        if (eventType == qt.QEvent.Resize
                and event.size() != event.oldSize()) or eventType in (
                    qt.QEvent.Show, qt.QEvent.FontChange, qt.QEvent.StyleChange):
            self.widget._scheduleResponsivePanelRefresh()
        elif (eventType == qt.QEvent.LayoutRequest
                and not getattr(self.widget, "_responsivePanelRefreshing", False)
                and not getattr(self.widget, "_responsivePanelRefreshPending", False)
                and self.widget._responsiveLayoutSignature() != getattr(
                    self.widget, "_responsiveLayoutState", None)):
            self.widget._scheduleResponsivePanelRefresh()
        return False


class SurgicalPlanningWidget(
    ScriptedLoadableModuleWidget,
    VTKObservationMixin,
):
    """Widget for the Surgical Planning module."""

    def __init__(self, parent=None) -> None:
        ScriptedLoadableModuleWidget.__init__(self, parent)
        VTKObservationMixin.__init__(self)

        self.logic = None
        self._parameterNode = None
        self._parameterNodeGuiTag = None
        # UI-layout guard: long MRML names and nested CTK sections must never
        # permanently expand the Slicer module dock.  The dock can still be
        # resized manually by the user; this flag only applies the compact
        # startup/reflow correction once per module instance.
        self._compactDockWidthApplied = False
        self._responsivePanelRefreshPending = False

    def setup(self) -> None:
        """Called when the module widget is initialized."""

        ScriptedLoadableModuleWidget.setup(self)

        # Load the Qt Designer UI.
        self.uiWidget = slicer.util.loadUI(
           self.resourcePath("UI/SurgicalPlanning.ui")
        )
        self.layout.addWidget(self.uiWidget)

        self.ui = slicer.util.childWidgetVariables(self.uiWidget)

        # Connect the MIP volume selector to the Slicer scene.
        self.ui.mipVolumeSelector.setMRMLScene(slicer.mrmlScene)

        # Create the Registration controls dynamically.
        self.setupRegistrationUi()

        # Connect core controls before optional advanced sections are built.
        # This keeps MIP and batch registration functional even if a newer
        # advanced section encounters a Slicer-version-specific UI error.
        self.ui.applyButton.connect(
            "clicked(bool)",
            self.onApplyButton,
        )
        self.ui.mipThicknessSlider.connect(
            "valueChanged(int)",
            self.onMipThicknessChanged,
        )
        self.ui.disableMipButton.connect(
            "clicked(bool)",
            self.onDisableMip,
        )
        self.registerButton.connect(
            "clicked(bool)",
            self.onRegisterButton,
        )

        # Central mask tools are created after Registration. Bone Preparation
        # is promoted to its own top-level workflow and is reordered before
        # Masks Preparation so CT-derived Bone_Mask is naturally available to
        # the optional CT-assisted brain-extraction route.
        self.setupMasksPreparationUi()

        # Group brain/ventricle/cranial-nerve/vessel workflows under one compact
        # top-level Brain Segments section. Bone Preparation is deliberately
        # kept outside this container.
        self.setupBrainSegmentsContainerUi()

        # Create Bone Preparation as an independent top-level workflow.
        self.setupBonePreparationUi()

        # Create reusable brain, optional high-detail cortical-surface, and
        # ventricular preparation workflows.
        self.setupBrainPreparationUi()
        self.setupDetailedCorticalSurfaceUi()
        self.setupVentriclePreparationUi()

        # Create the non-destructive Craniotomy Planning controls. The
        # section is moved to the very bottom after all optional workflows are
        # initialized, so Final 3D Model is penultimate and Craniotomy Planning
        # is the last workflow section.
        self.setupCraniotomyPlanningUi()

        # Create the Artery Preparation controls dynamically.
        self.setupVesselPreparationUi()

        # Create the Tumor Preparation controls dynamically.
        self.setupTumorPreparationUi()

        # Build a non-destructive composite 3D scene from the existing
        # editable skull, vessel, tumor, and cranial-nerve outputs.
        self.setupFinal3DModelUi()

        # Create the Cranial Nerve Preparation controls dynamically.
        # Do not let an optional workflow disable the established MIP,
        # registration, vessel, or tumor workflows.
        try:
            self.setupCranialNervePreparationUi()
        except Exception as error:
            logging.exception("Failed to initialize cranial-nerve planning UI")
            nerveSection = slicer.util.findChild(
                self.uiWidget,
                "cranialNervePreparationCollapsibleButton",
            )
            if nerveSection is not None:
                nerveLayout = nerveSection.layout()
                if nerveLayout is None:
                    nerveLayout = qt.QVBoxLayout()
                    nerveSection.setLayout(nerveLayout)
                warningLabel = qt.QLabel(
                    "CISS/Cranial Nerve Planning could not be initialized. "
                    "The other workflows remain available.\n\n" + str(error)
                )
                warningLabel.wordWrap = True
                nerveLayout.addWidget(warningLabel)

        # Move the established cranial-nerve and vessel sections into the
        # Brain Segments container, then enforce the requested top-level order.
        self.organizeBrainSegmentsAndWorkflow()

        # Final top-level workflow order: Registration, Bone Preparation, Masks
        # Preparation, Brain Segments, Tumor Preparation, Final 3D Model,
        # Craniotomy Planning. The former top-level MIP is nested as 2D Slab
        # MIP inside Artery Preparation.
        self.reorderBottomWorkflowSections()

        # Apply one typography/control-height policy to the complete module,
        # then release layout minimum-width constraints.  This keeps all
        # top-level and nested collapsibles visually consistent.
        self._applyConsistentUiStyling()
        self._applyResponsivePanelSizing()
        self._connectResponsiveCollapsibleRefreshes()

        # The former empty 3D Models placeholder is now configured by
        # setupFinal3DModelUi as the Final 3D Model scene builder.

        # Start with every workflow section closed. This keeps the module
        # compact and lets the user open only the workflow currently needed.
        for sectionName in (
            "mipCollapsibleButton",
            "registrationCollapsibleButton",
            "masksPreparationCollapsibleButton",
            "brainSegmentsCollapsibleButton",
            "bonePreparationCollapsibleButton",
            "brainPreparationCollapsibleButton",
            "detailedCortexCollapsibleButton",
            "ventriclePreparationCollapsibleButton",
            "craniotomyPlanningCollapsibleButton",
            "vesselPreparationCollapsibleButton",
            "surgicalPlanningCollapsibleButton",
            "modelsCollapsibleButton",
            "cranialNervePreparationCollapsibleButton",
        ):
            section = slicer.util.findChild(self.uiWidget, sectionName)
            if section is not None:
                section.collapsed = True
        for nestedSectionName in (
            "arterialSourcesSetupCollapsibleButton",
            "arterialPreviewToolsCollapsibleButton",
            "recommendedArterialReconstructionCollapsibleButton",
            "arterialAdvancedMethodsCollapsibleButton",
            "arterialFinalModelCollapsibleButton",
            "quickAngioCollapsibleButton",
            "ctaBoneSuppressionCollapsibleButton",
            "tofMultithresholdCollapsibleButton",
            "distalCorticalArteriesCollapsibleButton",
            "detailedVascularCollapsibleButton",
            "combineVascularCollapsibleButton",
            "vesselSettingsCollapsibleButton",
            "extendedVesselCollapsibleButton",
            "automaticRegistrationCollapsibleButton",
            "manualRegistrationCollapsibleButton",
            "nerveSegmentationCollapsibleButton",
            "expectedCourseCollapsibleButton",
            "movingVolumesCollapsibleButton",
            "mriBrainExtractionCollapsibleButton",
            "ctAssistedIntracranialCollapsibleButton",
            "warpAdvancedCollapsibleButton",
            "hdBetAdvancedCollapsibleButton",
            "corticalMRIMethodCollapsibleButton",
            "corticalRobustMethodCollapsibleButton",
            "corticalParcellationCollapsibleButton",
            "corticalMRIAdvancedCollapsibleButton",
            "corticalRobustAdvancedCollapsibleButton",
            "corticalParcellationAdvancedCollapsibleButton",
            "craniotomyCreationCollapsibleButton",
            "refineBoneFlapCollapsibleButton",
            "craniotomyOutputDisplayCollapsibleButton",
        ):
            nestedSection = getattr(self, nestedSectionName, None)
            if nestedSection is not None:
                nestedSection.collapsed = True

        # Connect the complete UI to the Slicer scene.
        self.uiWidget.setMRMLScene(slicer.mrmlScene)

        # One final geometry pass after all sections have been collapsed and
        # the MRML scene has been connected. This avoids starting the module
        # with stale size hints that only correct themselves after the user
        # drags the module-panel splitter.
        self._compactDockWidthApplied = False
        self._scheduleResponsivePanelRefresh()

        # Create the module logic.
        self.logic = SurgicalPlanningLogic()

        # Observe scene closing and reopening.
        self.addObserver(
            slicer.mrmlScene,
            slicer.mrmlScene.StartCloseEvent,
            self.onSceneStartClose,
        )

        self.addObserver(
            slicer.mrmlScene,
            slicer.mrmlScene.EndCloseEvent,
            self.onSceneEndClose,
        )
        for sceneEventName in ("EndImportEvent", "EndRestoreEvent"):
            sceneEvent = getattr(slicer.mrmlScene, sceneEventName, None)
            if sceneEvent is not None:
                self.addObserver(
                    slicer.mrmlScene,
                    sceneEvent,
                    self.onSceneImportRestoreEnd,
                )

        # Keep Enable MIP available.
        self.ui.applyButton.enabled = True

        # Initialize the parameter node.
        self.initializeParameterNode()

