            ("Parcellation", "Parcellation:"),
            ("Ventricles", "Ventricles:"),
            ("Skull", "Skull:"),
            ("Arteries", "Arteries_Combined:"),
            ("QuickArteries", "Quick arteries:"),
            ("ThresholdArteries", "Threshold arteries:"),
            ("LargeArteries", "Large arteries:"),
            ("ExtendedArteries", "Extended arteries:"),
            ("Tumor", "Tumor:"),
